import React from 'react';
import './ProductList.css';

const ProductList = ({ products, onQuantityChange }) => {
  return (
    <div className="product-list-container">
      <h2>Our Bakery Items</h2>
      <div className="products-grid">
        {products.map((product) => (
          <div key={product.name} className={`product-card ${product.stock === 0 ? 'out-of-stock' : ''}`}>
            <img 
              src={`/images/${product.name.toLowerCase()}.png`} 
              alt={product.name} 
              className="product-image"
            />
            <h3>{product.name}</h3>
            <p>${product.price.toFixed(2)}</p>
            <div className="quantity-control">
              <button 
                onClick={() => onQuantityChange(product.name, -1)} 
                disabled={product.quantity <= 0}
              >
                -
              </button>
              <span>{product.quantity}</span>
              <button 
                onClick={() => onQuantityChange(product.name, 1)} 
                disabled={product.quantity >= product.stock}
              >
                +
              </button>
            </div>
            <p className="stock-info">
              {product.stock > 0 ? `${product.stock} in stock` : 'Out of stock'}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ProductList;
